mapper.select:
SELECT s.id AS settlementId, s.settlement_no AS settlementNo, s.repair_order_id AS orderId, o.order_no AS orderNo, c.unit_name AS customerName, COALESCE(s.total_income, 0) AS incomeAmount, COALESCE(s.total_cost, 0) AS costAmount, COALESCE(s.profit_amount, 0) AS profit, CASE WHEN COALESCE(s.total_income, 0) > 0 THEN ROUND(COALESCE(s.profit_amount, 0) / s.total_income * 100, 2) ELSE 0 END AS profitRate, s.update_time AS settleTime FROM eoms_repair_settlement s LEFT JOIN eoms_repair_order o ON s.repair_order_id = o.id LEFT JOIN psi_unit c ON o.customer_id = c.id AND c.deleted = 0 WHERE s.del_flag = '0' AND s.status = 'CONFIRMED'
AND s.update_time >= #{beginMonth}
AND s.update_time < #{endMonthNext}
AND c.unit_name LIKE CONCAT(#{customerName}, '%') AND c.unit_name LIKE CONCAT('%', #{customerName}, '%')
AND o.order_no LIKE CONCAT(#{orderNo}, '%')
ORDER BY s.update_time DESC

SELECT COALESCE(SUM(s.total_income), 0) AS totalIncome, COALESCE(SUM(s.total_cost), 0) AS totalCost, COALESCE(SUM(s.profit_amount), 0) AS totalProfit, CASE WHEN SUM(s.total_income) > 0 THEN ROUND(SUM(s.profit_amount) / SUM(s.total_income) * 100, 2) ELSE 0 END AS profitRate, COUNT(*) AS orderCount FROM eoms_repair_settlement s LEFT JOIN eoms_repair_order o ON s.repair_order_id = o.id LEFT JOIN psi_unit c ON o.customer_id = c.id AND c.deleted = 0 WHERE s.del_flag = '0' AND s.status = 'CONFIRMED'
AND s.update_time >= #{beginMonth}
AND s.update_time < #{endMonthNext}
AND c.unit_name LIKE CONCAT(#{customerName}, '%') AND c.unit_name LIKE CONCAT('%', #{customerName}, '%')
AND o.order_no LIKE CONCAT(#{orderNo}, '%')
